#include <stdio.h>

#define MAX_EQ 200
#define MAX_VAR 676

int coeff[MAX_EQ][MAX_VAR];
int grid[100][100];
long long rhs[MAX_EQ];
int present[MAX_VAR];
int solved[MAX_VAR];
long long value[MAX_VAR];

int main(void) {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    char name[3];

    for (int i = 0; i < L; i++) {
        for (int j = 0; j < C; j++) {
            scanf("%2s", name);
            int v = (name[0] - 'a') * 26 + (name[1] - 'a');
            grid[i][j] = v;
            coeff[i][v]++;
            present[v] = 1;
        }
        scanf("%lld", &rhs[i]);
    }

    for (int j = 0; j < C; j++) {
        scanf("%lld", &rhs[L + j]);
        for (int i = 0; i < L; i++)
            coeff[L + j][grid[i][j]]++;
    }

    int total = L + C;
    int remaining = 0;
    for (int v = 0; v < MAX_VAR; v++)
        remaining += present[v];

    while (remaining > 0) {
        int found = 0;

        for (int e = 0; e < total && !found; e++) {
            int unknown = -1;
            int count = 0;

            for (int v = 0; v < MAX_VAR; v++) {
                if (!solved[v] && coeff[e][v] > 0) {
                    unknown = v;
                    count++;
                    if (count > 1) break;
                }
            }

            if (count == 1) {
                value[unknown] = rhs[e] / coeff[e][unknown];
                solved[unknown] = 1;
                remaining--;

                for (int k = 0; k < total; k++)
                    rhs[k] -= (long long)coeff[k][unknown] * value[unknown];

                found = 1;
            }
        }
    }

    for (int v = 0; v < MAX_VAR; v++) {
        if (present[v])
            printf("%c%c %lld\n", 'a' + v / 26, 'a' + v % 26, value[v]);
    }

    return 0;
}
